CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL);
CREATE TABLE expense_groups (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(255) NOT NULL, created_by_id BIGINT NOT NULL REFERENCES users(id));
CREATE TABLE group_members (group_id BIGINT NOT NULL REFERENCES expense_groups(id), user_id BIGINT NOT NULL REFERENCES users(id), PRIMARY KEY (group_id, user_id));
CREATE TABLE expense (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, group_id BIGINT NOT NULL REFERENCES expense_groups(id), paid_by_id BIGINT NOT NULL REFERENCES users(id), description VARCHAR(255) NOT NULL, total_amount NUMERIC(19,2) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE expense_split (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, expense_id BIGINT NOT NULL REFERENCES expense(id), user_id BIGINT NOT NULL REFERENCES users(id), owed_amount NUMERIC(19,2) NOT NULL);
CREATE TABLE group_invitation (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, group_id BIGINT NOT NULL REFERENCES expense_groups(id), invited_by_id BIGINT NOT NULL REFERENCES users(id), invited_email VARCHAR(255) NOT NULL, token VARCHAR(255) NOT NULL UNIQUE, status VARCHAR(20) NOT NULL, expires_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_expense_group ON expense(group_id);
CREATE INDEX idx_invitation_email_status ON group_invitation(invited_email, status);
